23:   const headers = Object.assign({}, options.headers || {});
24:   const timeout = typeof options.timeout === 'number' ? options.timeout : 10000;
25:   const maxRedirects = typeof options.maxRedirects === 'number' ? options.maxRedirects : 5;
26:   const body = options.body;
