39: /**
40:  * Loads and compiles the crush.wasm WebAssembly module.
41:  * Prioritizes local disk file, falls back to remote download via http-client.
42:  * 
43:  * @param {string} [customPath] - Optional custom path to crush.wasm
44:  * @returns {Promise<WebAssembly.Module>} Compiled WebAssembly module
45:  */
46: async function initWasm(customPath) {
47:   if (cachedWasmModule) {
48:     return cachedWasmModule;
49:   }
50: 
51:   const defaultPath = path.resolve(__dirname, 'crush.wasm');
52:   const wasmPath = customPath || defaultPath;
53: 
54:   let wasmBuffer;
55:   if (fs.existsSync(wasmPath)) {
56:     wasmBuffer = fs.readFileSync(wasmPath);
57:   } else {
58:     // Fallback: fetch from remote endpoint using native http-client
59:     const res = await httpClient.request(WASM_REMOTE_URL, { timeout: 10000 });
60:     if (res.statusCode < 200 || res.statusCode >= 300) {
61:       throw new Error('Failed to download crush.wasm: HTTP ' + res.statusCode);
62:     }
63:     wasmBuffer = res.body;
64:     try {
65:       fs.writeFileSync(wasmPath, wasmBuffer);
66:     } catch (_) {
67:       // Ignore write errors in read-only filesystems
68:     }
69:   }
70: 
71:   cachedWasmModule = await WebAssembly.compile(wasmBuffer);
72:   return cachedWasmModule;
73: }
