119: /**
120:  * Executes request sealing in crush.wasm.
121:  * 
122:  * @param {WebAssembly.Instance} wasmInstance
123:  * @param {object} params
124:  * @returns {{ responseKey: Buffer, keyId: number, ephemeralPublic: Buffer, ciphertextBody: Buffer }}
125:  */
126: function sealRequest(wasmInstance, params) {
127:   const server = params.server;
128:   const type = params.type;
129:   const tmdbId = params.tmdbId;
130:   const season = params.season;
131:   const episode = params.episode;
132: 
133:   const exports = wasmInstance.exports;
134:   const wasmType = (type === 'tv' || type === 'series') ? 'series' : 'movie';
135:   
136:   const payloadObj = { tmdb: String(tmdbId) };
137:   if (wasmType === 'series') {
138:     payloadObj.season = String(season || 1);
139:     payloadObj.episode = String(episode || 1);
140:   }
141: 
142:   const payloadJson = JSON.stringify({
143:     path: '/' + server + '/' + wasmType,
144:     payload: payloadObj
145:   });
146: 
147:   const encodedPayload = Buffer.from(payloadJson, 'utf8');
148:   const randBytes = crypto.randomBytes(RANDOM_SEED_LEN);
149: 
150:   const payloadPtr = exports.alloc(encodedPayload.length);
151:   const randPtr = exports.alloc(randBytes.length);
152:   const outPtr = exports.alloc(OUT_BUF_MAX);
153: 
154:   const mem = new Uint8Array(exports.memory.buffer);
155:   mem.set(encodedPayload, payloadPtr);
156:   mem.set(randBytes, randPtr);
157: 
158:   const sealedLen = exports.seal_request(
159:     payloadPtr, encodedPayload.length,
160:     randPtr, randBytes.length,
161:     outPtr, OUT_BUF_MAX
162:   );
163: 
164:   if (sealedLen <= HEADER_LEN) {
165:     exports.dealloc(payloadPtr, encodedPayload.length);
166:     exports.dealloc(randPtr, randBytes.length);
167:     exports.dealloc(outPtr, OUT_BUF_MAX);
168:     throw new Error('WASM seal_request returned invalid length: ' + sealedLen);
169:   }
170: 
171:   const sealedBuffer = Buffer.from(exports.memory.buffer, outPtr, sealedLen);
172:   const responseKey = Buffer.from(sealedBuffer.subarray(0, AES_KEY_LEN));
173:   const keyId = sealedBuffer[AES_KEY_LEN];
174:   const ephemeralPublic = Buffer.from(sealedBuffer.subarray(AES_KEY_LEN + KEY_ID_LEN, HEADER_LEN));
175:   const ciphertextBody = Buffer.from(sealedBuffer.subarray(HEADER_LEN, sealedLen));
176: 
177:   // Free allocated linear memory
178:   exports.dealloc(payloadPtr, encodedPayload.length);
179:   exports.dealloc(randPtr, randBytes.length);
180:   exports.dealloc(outPtr, OUT_BUF_MAX);
181: 
182:   return { responseKey: responseKey, keyId: keyId, ephemeralPublic: ephemeralPublic, ciphertextBody: ciphertextBody };
183: }
