221: /**
222:  * Attempts stream resolution on a single named server node.
223:  * 
224:  * @private
225:  */
226: async function resolveSingleServer(params) {
227:   const server = params.server;
228:   const type = params.type;
229:   const tmdbId = params.tmdbId;
230:   const season = params.season;
231:   const episode = params.episode;
232:   const wasmModule = params.wasmModule;
233: 
234:   const instance = await WebAssembly.instantiate(wasmModule);
235:   const sealed = sealRequest(instance, {
236:     server: server,
237:     type: type,
238:     tmdbId: tmdbId,
239:     season: season,
240:     episode: episode
241:   });
242: 
243:   const gatewayRes = await httpClient.request(GATEWAY_URL, {
244:     method: 'POST',
245:     headers: {
246:       'Content-Type': 'text/plain;charset=UTF-8',
247:       'Origin': 'https://cinejoy.pk',
248:       'Referer': 'https://cinejoy.pk/',
249:       'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.5359.211 Safari/537.36'
250:     },
251:     body: sealed.ciphertextBody,
252:     timeout: 10000
253:   });
254: 
255:   if (gatewayRes.statusCode < 200 || gatewayRes.statusCode >= 300) {
256:     throw new Error('Gateway returned HTTP ' + gatewayRes.statusCode);
257:   }
258: 
259:   const decrypted = decryptResponse(gatewayRes.body, sealed.responseKey, sealed.keyId, sealed.ephemeralPublic);
260: 
261:   if (decrypted.status !== 200) {
262:     const errorMsg = (decrypted.data && decrypted.data.error) ? decrypted.data.error : ('Status ' + decrypted.status);
263:     throw new Error(server + ': ' + errorMsg);
264:   }
265: 
266:   const stream = (decrypted.data && decrypted.data.stream && decrypted.data.stream[0]) ? decrypted.data.stream[0] : null;
267:   if (!stream || !stream.playlist) {
268:     throw new Error(server + ': No playable playlist returned');
269:   }
270: 
271:   return {
272:     playlist: stream.playlist,
273:     captions: stream.captions || [],
274:     server: server,
275:     rawStream: stream
276:   };
277: }
